'use strict';

// MODULES //

var tape = require( 'tape' );
var isAlmostSameValue = require( '@stdlib/assert/is-almost-same-value' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var PINF = require( '@stdlib/constants/float64/pinf' );
var NINF = require( '@stdlib/constants/float64/ninf' );
var gelu = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof gelu, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns `NaN` when provided `NaN`', function test( t ) {
	var y = gelu( NaN );
	t.strictEqual( isnan( y ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns `0.0` when provided `0.0`', function test( t ) {
	var y = gelu( 0.0 );
	t.strictEqual( y, 0.0, 'returns expected value' );
	t.end();
});

tape( 'the function returns `+Infinity` when provided `+Infinity`', function test( t ) {
	var y = gelu( PINF );
	t.strictEqual( y, PINF, 'returns expected value' );
	t.end();
});

tape( 'the function returns `0.0` when provided `-Infinity`', function test( t ) {
	var y = gelu( NINF );
	t.strictEqual( y, 0.0, 'returns expected value' );
	t.end();
});

tape( 'the function evaluates the GELU function for representative inputs', function test( t ) {
	var expected;
	var actual;
	var values;
	var i;

	values = [
		1.0,
		-1.0,
		2.0,
		-2.0,
		5.0,
		-5.0
	];
	expected = [
		0.8413447460685429,
		-0.15865525393145705,
		1.9544997361036415,
		-0.04550026389635842,
		4.999998566742141,
		-0.0000014332578593959682
	];

	for ( i = 0; i < values.length; i++ ) {
		actual = gelu( values[ i ] );
		t.strictEqual( isAlmostSameValue( actual, expected[ i ], 2 ), true, 'returns expected value for ' + values[ i ] );
	}
	t.end();
});
